(()=>{
const $=id=>document.getElementById(id),core=AftershockModel,form=$('prediction-form');let metadata,bundle,last,loading;
function clearResult(){last=null;$('result-values').hidden=true;$('result-empty').hidden=false;$('prediction-export').hidden=true}
const read=()=>{const [year,month,day]=$('predict-date').value.split('-').map(Number),[hour,min]=$('predict-time').value.split(':').map(Number);const v={year,month,day,hour,min};for(const k of ['sec','lat','lon','depth','class'])v[k]=$('predict-'+k).value.trim()===''?NaN:Number($('predict-'+k).value);return v};
function normalized(){try{const v=read();core.validate(v);$('normalized-time').textContent='Model input (UTC): '+new Date(core.timestamp(v)).toISOString().replace('T',' ').replace('.000Z',' UTC')}catch{$('normalized-time').textContent='Complete the fields to see the normalized UTC time.'}}
function example(){const v=metadata?.example||{year:2018,month:2,day:14,hour:23,min:21,sec:505,lat:38.46,lon:73.45,depth:60,class:10.7};$('predict-date').value=`${v.year}-${String(v.month).padStart(2,'0')}-${String(v.day).padStart(2,'0')}`;$('predict-time').value=`${String(v.hour).padStart(2,'0')}:${String(v.min).padStart(2,'0')}`;for(const k of ['sec','lat','lon','depth','class'])$('predict-'+k).value=v[k];normalized();$('prediction-status').textContent='Sample loaded. Select Predict aftershock to calculate.';}
async function loadModel(){if(bundle)return bundle;if(!loading)loading=fetch('model.json').then(r=>{if(!r.ok)throw Error('Model file unavailable. Please retry.');return r.json()}).then(x=>bundle=x).catch(e=>{loading=null;throw e});return loading}
form.addEventListener('input',()=>{normalized();clearResult();$('prediction-status').textContent='Inputs changed. Run prediction to update the result.'});
$('load-example').addEventListener('click',clearResult);
$('load-example').addEventListener('click',example);
form.addEventListener('submit',async e=>{e.preventDefault();const status=$('prediction-status'),button=$('prediction-submit');status.classList.remove('error');try{const v=read();core.validate(v);button.disabled=true;form.querySelectorAll('input, #load-example').forEach(el=>el.disabled=true);button.textContent='Calculating…';status.textContent='Loading the trained model and calculating your estimate…';const model=await loadModel(),p=core.predict(model,v);last={input:v,prediction:p,model:{selected:model.metadata.selected,trainingPairs:model.metadata.trainingPairs,secondsScale:1},notice:'Historical research estimate; not an earthquake warning.'};$('result-empty').hidden=true;$('result-values').hidden=false;$('result-time').textContent=p.timestamp.replace('T',' ').replace('Z',' UTC');$('result-time').dateTime=p.timestamp;$('result-elapsed').textContent=`+ ${(p.elapsedSeconds/3600).toLocaleString(undefined,{maximumFractionDigits:2})} hours after the normalized main shock`;
for(const k of ['lat','lon','depth','class'])$('result-'+k).textContent=p[k].toFixed(k==='lat'||k==='lon'?4:2);
const outside=core.fields.filter(k=>v[k]<model.metadata.ranges[k][0]||v[k]>model.metadata.ranges[k][1]);$('range-warning').hidden=!outside.length;$('range-warning').textContent='Outside the training range: '+outside.join(', ')+'. Treat this extrapolation with extra caution.';$('prediction-export').hidden=false;status.textContent='Prediction complete. Results use your current inputs.';
}catch(err){status.classList.add('error');status.textContent=err.message||'Unable to calculate. Check the inputs and try again.'}finally{form.querySelectorAll('input, #load-example').forEach(el=>el.disabled=false);button.disabled=false;button.innerHTML='Predict aftershock <span>↗</span>'}});
$('prediction-export').addEventListener('click',()=>{if(!last)return;const url=URL.createObjectURL(new Blob([JSON.stringify(last,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='aftershock-prediction.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
fetch('model-metadata.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{metadata=m;for(const k of ['lat','lon','depth','class'])$('mae-'+k).textContent=m.mae[k].toFixed(k==='lat'||k==='lon'?3:2);$('time-mae').textContent=m.elapsedHoursMAE.toLocaleString(undefined,{maximumFractionDigits:1});$('selected-models').textContent=Object.entries(m.selected).map(([k,v])=>`${k}: ${v}`).join(' · ');}).catch(()=>{$('validation-summary').textContent='Validation metadata could not be loaded. Reload to retry.'});example();
})();
